public class InnerConnectionTypeConnectorAuthenticationConfigurationFactory(Action<Humidifier.Glue.ConnectionTypeTypes.ConnectorAuthenticationConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.Glue.ConnectionTypeTypes.ConnectorAuthenticationConfiguration>
{

    internal InnerConnectionTypeCustomAuthenticationPropertiesFactory CustomAuthenticationPropertiesFactory { get; set; }

    internal InnerConnectionTypeConnectorOAuth2PropertiesFactory OAuth2PropertiesFactory { get; set; }

    internal InnerConnectionTypeBasicAuthenticationPropertiesFactory BasicAuthenticationPropertiesFactory { get; set; }

    protected override Humidifier.Glue.ConnectionTypeTypes.ConnectorAuthenticationConfiguration Create()
    {
        var connectorAuthenticationConfigurationResult = CreateConnectorAuthenticationConfiguration();
        factoryAction?.Invoke(connectorAuthenticationConfigurationResult);

        return connectorAuthenticationConfigurationResult;
    }

    private Humidifier.Glue.ConnectionTypeTypes.ConnectorAuthenticationConfiguration CreateConnectorAuthenticationConfiguration()
    {
        var connectorAuthenticationConfigurationResult = new Humidifier.Glue.ConnectionTypeTypes.ConnectorAuthenticationConfiguration();

        return connectorAuthenticationConfigurationResult;
    }
    public override void CreateChildren(Humidifier.Glue.ConnectionTypeTypes.ConnectorAuthenticationConfiguration result)
    {
        base.CreateChildren(result);

        result.CustomAuthenticationProperties ??= CustomAuthenticationPropertiesFactory?.Build();
        result.OAuth2Properties ??= OAuth2PropertiesFactory?.Build();
        result.BasicAuthenticationProperties ??= BasicAuthenticationPropertiesFactory?.Build();
    }

} // End Of Class

